String.prototype.trim = function () { return this.replace(/(^\s*)|(\s*$)/g, ""); }

//参数——中文字符串
//返回值——拼音首字母串数组
function getFirstLetterList(str) {
  if (typeof (str) != "string")
    throw new Error(-1, "请传入字符串类型的参数!");
  var arrResult = new Array(); //保存中间结果的数组
  for (var i = 0, len = str.length; i < len; i++) {
    //获得unicode码
    var ch = str.charAt(i);
    //检查该unicode码是否在处理范围之内,在则返回该码对映汉字的拼音首字母,不在则调用其它函数处理
    arrResult.push(checkCh(ch));
  }
  //处理arrResult,返回所有可能的拼音首字母串数组
  return mkRslt(arrResult);
}

// 判断字符串是否全是中文
function isAllChinese(str) {
  return /^[\u4E00-\u9FA5]+$/.test(str);
}

// 判断字符是否为中文
function isChinese(char) {
  return /^[\u4E00-\u9FA5]$/.test(char);
}

// 中文拼音名称排序
const sortListByCN = (vodList, key, order) => {
  if (!key) {
    return vodList
  }
  order = order || 'asc'; // 默认正序
  let ASCarr = vodList.sort((a, b) => {
    a = a[key];
    b = b[key];
    // 数字排在字符串前面
    if (typeof a === 'number' && typeof b === 'string') {
      return -1;
    }

    if (typeof a === 'string' && typeof b === 'number') {
      return 1;
    }

    // 当存在非数字时
    if (isNaN(a) || isNaN(b)) {

      // 全汉字的排在非全汉字的后面
      if (isAllChinese(a) && !isAllChinese(b)) {
        return 1;
      }

      if (!isAllChinese(a) && isAllChinese(b)) {
        return -1;
      }

      // 存在非数字的数据时，都转为字符串进行比较
      a = a.toString();
      b = b.toString();

      let result = 0;

      // 依次比较两个字符串的各项字符
      for (let index = 0; index < ((a.length - b.length) ? b.length : a.length); index++) {

        // 汉字排在非汉字的后面
        if (!isChinese(a[index]) && isChinese(b[index])) {
          result = -1;
        }

        if (isChinese(a[index]) && !isChinese(b[index])) {
          result = 1;
        }

        // 若两个汉字进行比较，则比较他们的拼音首字母
        if (isChinese(a[index]) && isChinese(b[index])) {
          let pinyinA = getFirstLetterList(a[index]).toString();
          let pinyinB = getFirstLetterList(b[index]).toString();

          result = pinyinA.localeCompare(pinyinB, 'zh-Hans-CN', { sensitivity: 'accent' });
        }

        // 若已经比较出结果，则跳出循环，不再继续比较剩余字符
        if (result !== 0) {
          break
        }
      }

      // 只要有一个无法转换为数字——转换为字符串进行比较——先按字符排序，然后按照数字排序
      return result || a.toString().localeCompare(b.toString(), 'zh-Hans-CN', { sensitivity: 'accent' });
    } else {
      // 都能转换为数字——转换为数字进行比较——从小到大排序
      return Number(a) - Number(b);
    }
  });
  if (order === 'desc') {
    ASCarr.reverse();
  }
  return ASCarr
};
const peq = new Uint32Array(0x10000);
const myers_32 = (a, b) => {
  const n = a.length;
  const m = b.length;
  const lst = 1 << (n - 1);
  let pv = -1;
  let mv = 0;
  let sc = n;
  let i = n;
  while (i--) {
    peq[a.charCodeAt(i)] |= 1 << i;
  }
  for (i = 0; i < m; i++) {
    let eq = peq[b.charCodeAt(i)];
    const xv = eq | mv;
    eq |= ((eq & pv) + pv) ^ pv;
    mv |= ~(eq | pv);
    pv &= eq;
    if (mv & lst) {
      sc++;
    }
    if (pv & lst) {
      sc--;
    }
    mv = (mv << 1) | 1;
    pv = (pv << 1) | ~(xv | mv);
    mv &= xv;
  }
  i = n;
  while (i--) {
    peq[a.charCodeAt(i)] = 0;
  }
  return sc;
};
const myers_x = (b, a) => {
  const n = a.length;
  const m = b.length;
  const mhc = [];
  const phc = [];
  const hsize = Math.ceil(n / 32);
  const vsize = Math.ceil(m / 32);
  for (let i = 0; i < hsize; i++) {
    phc[i] = -1;
    mhc[i] = 0;
  }
  let j = 0;
  for (; j < vsize - 1; j++) {
    let mv = 0;
    let pv = -1;
    const start = j * 32;
    const vlen = Math.min(32, m) + start;
    for (let k = start; k < vlen; k++) {
      peq[b.charCodeAt(k)] |= 1 << k;
    }
    for (let i = 0; i < n; i++) {
      const eq = peq[a.charCodeAt(i)];
      const pb = (phc[(i / 32) | 0] >>> i) & 1;
      const mb = (mhc[(i / 32) | 0] >>> i) & 1;
      const xv = eq | mv;
      const xh = ((((eq | mb) & pv) + pv) ^ pv) | eq | mb;
      let ph = mv | ~(xh | pv);
      let mh = pv & xh;
      if ((ph >>> 31) ^ pb) {
        phc[(i / 32) | 0] ^= 1 << i;
      }
      if ((mh >>> 31) ^ mb) {
        mhc[(i / 32) | 0] ^= 1 << i;
      }
      ph = (ph << 1) | pb;
      mh = (mh << 1) | mb;
      pv = mh | ~(xv | ph);
      mv = ph & xv;
    }
    for (let k = start; k < vlen; k++) {
      peq[b.charCodeAt(k)] = 0;
    }
  }
  let mv = 0;
  let pv = -1;
  const start = j * 32;
  const vlen = Math.min(32, m - start) + start;
  for (let k = start; k < vlen; k++) {
    peq[b.charCodeAt(k)] |= 1 << k;
  }
  let score = m;
  for (let i = 0; i < n; i++) {
    const eq = peq[a.charCodeAt(i)];
    const pb = (phc[(i / 32) | 0] >>> i) & 1;
    const mb = (mhc[(i / 32) | 0] >>> i) & 1;
    const xv = eq | mv;
    const xh = ((((eq | mb) & pv) + pv) ^ pv) | eq | mb;
    let ph = mv | ~(xh | pv);
    let mh = pv & xh;
    score += (ph >>> (m - 1)) & 1;
    score -= (mh >>> (m - 1)) & 1;
    if ((ph >>> 31) ^ pb) {
      phc[(i / 32) | 0] ^= 1 << i;
    }
    if ((mh >>> 31) ^ mb) {
      mhc[(i / 32) | 0] ^= 1 << i;
    }
    ph = (ph << 1) | pb;
    mh = (mh << 1) | mb;
    pv = mh | ~(xv | ph);
    mv = ph & xv;
  }
  for (let k = start; k < vlen; k++) {
    peq[b.charCodeAt(k)] = 0;
  }
  return score;
};
const distance = (a, b) => {
  if (a.length < b.length) {
    const tmp = b;
    b = a;
    a = tmp;
  }
  if (b.length === 0) {
    return a.length;
  }
  if (a.length <= 32) {
    return myers_32(a, b);
  }
  return myers_x(a, b);
};

