function search(wd, quick) {
  // print(__drives);
  // print('可搜索的openlist驱动:' + searchDriver);
  if (!searchDriver || !wd) {
    return JSON.stringify({
      'list': []
    });
  } else {
    let driver = __drives[searchDriver];
    wd = wd.split(' ').filter(it => it.trim()).join('+');
    print(driver);

    let pattern = new RegExp(driver.realStartPage.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '[^/]*', 'g');
    let surl = driver.server + driver.api.search;

    // print('搜索链接:' + surl);
    let res_search = http.post(surl, {
      data: {
        keywords: wd,
        page: 1,
        per_page: 50,
        scope: 1
      }, headers: driver.headers
    });

    // console.log('搜索结果:' + JSON.stringify(res_search.json()));
    let vods = res_search.json().data.content.reduce((acc, item) => {
      // 只处理文件（过滤文件夹）
      // 由于openlist 的索引是输出真是路径，有些用户的「根目录」本非真正的根目录，所以要去掉其中重叠部分
      let parent = item.parent.replace(pattern, '');
      acc.push({
        vod_name: item.name,
        vod_id: searchDriver + '$' + parent + '/' + item.name + '#search##all#',
        vod_tag: item.is_dir ? 'folder' : 'file',
        vod_pic: PicOpenlist,
        vod_remarks: searchDriver
      });
      return acc;
    }, []); // 初始值为空数组
    vods = vods.slice(0, limit_search_show);
    return JSON.stringify({
      'list': vods
    });
  }
}

function get_size(sz) {
  if (sz <= 0) {
    return "";
  }
  let filesize = "";
  if (sz > 1024 * 1024 * 1024 * 1024.0) {
    sz /= (1024 * 1024 * 1024 * 1024.0);
    filesize = "TB";
  } else if (sz > 1024 * 1024 * 1024.0) {
    sz /= (1024 * 1024 * 1024.0);
    filesize = "GB";
  } else if (sz > 1024 * 1024.0) {
    sz /= (1024 * 1024.0);
    filesize = "MB";
  } else if (sz > 1024.0) {
    sz /= 1024.0;
    filesize = "KB";
  } else {
    filesize = "B";
  }
  // 转成字符串
  let sizeStr = sz.toFixed(2) + filesize,
    // 获取小数点处的索引
    index = sizeStr.indexOf("."),
    // 获取小数点后两位的值
    dou = sizeStr.substr(index + 1, 2);
  if (dou === "00") {
    return sizeStr.substring(0, index) + sizeStr.substr(index + 3, 2);
  } else {
    return sizeStr;
  }
}

// 相似度获取
function levenshteinDistance(str1, str2) {
  return 100 - 100 * distance(str1, str2) / Math.max(str1.length, str2.length);
}

/**
 * 自然排序
 * ["第1集","第10集","第20集","第2集","1","2","10","12","23","01","02"].sort(naturalSort())
 * @param options {{key,caseSensitive, order: string}}
 */
function naturalSort(options) {
  if (!options) {
    options = {};
  }

  return function (a, b) {
    if (options.key) {
      a = a[options.key];
      b = b[options.key];
    }
    var EQUAL = 0;
    var GREATER = (options.order === 'desc' ?
      -1 :
      1
    );
    var SMALLER = -GREATER;

    var re = /(^-?[0-9]+(\.?[0-9]*)[df]?e?[0-9]?$|^0x[0-9a-f]+$|[0-9]+)/gi;
    var sre = /(^[ ]*|[ ]*$)/g;
    var dre = /(^([\w ]+,?[\w ]+)?[\w ]+,?[\w ]+\d+:\d+(:\d+)?[\w ]?|^\d{1,4}[\/\-]\d{1,4}[\/\-]\d{1,4}|^\w+, \w+ \d+, \d{4})/;
    var hre = /^0x[0-9a-f]+$/i;
    var ore = /^0/;

    var normalize = function normalize(value) {
      var string = '' + value;
      return (options.caseSensitive ?
        string :
        string.toLowerCase()
      );
    };

    // Normalize values to strings
    var x = normalize(a).replace(sre, '') || '';
    var y = normalize(b).replace(sre, '') || '';

    // chunk/tokenize
    var xN = x.replace(re, '\0$1\0').replace(/\0$/, '').replace(/^\0/, '').split('\0');
    var yN = y.replace(re, '\0$1\0').replace(/\0$/, '').replace(/^\0/, '').split('\0');

    // Return immediately if at least one of the values is empty.
    if (!x && !y) return EQUAL;
    if (!x && y) return GREATER;
    if (x && !y) return SMALLER;

    // numeric, hex or date detection
    var xD = parseInt(x.match(hre)) || (xN.length != 1 && x.match(dre) && Date.parse(x));
    var yD = parseInt(y.match(hre)) || xD && y.match(dre) && Date.parse(y) || null;
    var oFxNcL, oFyNcL;

    // first try and sort Hex codes or Dates
    if (yD) {
      if (xD < yD) return SMALLER;
      else if (xD > yD) return GREATER;
    }

    // natural sorting through split numeric strings and default strings
    for (var cLoc = 0, numS = Math.max(xN.length, yN.length); cLoc < numS; cLoc++) {

      // find floats not starting with '0', string or 0 if not defined (Clint Priest)
      oFxNcL = !(xN[cLoc] || '').match(ore) && parseFloat(xN[cLoc]) || xN[cLoc] || 0;
      oFyNcL = !(yN[cLoc] || '').match(ore) && parseFloat(yN[cLoc]) || yN[cLoc] || 0;

      // handle numeric vs string comparison - number < string - (Kyle Adams)
      if (isNaN(oFxNcL) !== isNaN(oFyNcL)) return (isNaN(oFxNcL)) ? GREATER : SMALLER;

      // rely on string comparison if different types - i.e. '02' < 2 != '02' < '2'
      else if (typeof oFxNcL !== typeof oFyNcL) {
        oFxNcL += '';
        oFyNcL += '';
      }
      if (oFxNcL < oFyNcL) return SMALLER;
      if (oFxNcL > oFyNcL) return GREATER;
    }
    return EQUAL;
  };
}
// 完整名称排序
const sortListByName = (vodList, key, order) => {
  if (!key) {
    return vodList
  }
  order = order || 'asc'; // 默认正序
  // 排序键,顺序,区分大小写
  return vodList.sort(naturalSort({ key: key, order: order, caseSensitive: true }))
};

const getTimeInt = (timeStr) => {
  return (new Date(timeStr)).getTime();
};

// 时间
const sortListByTime = (vodList, key, order) => {
  if (!key) {
    return vodList
  }
  let ASCarr = vodList.sort((a, b) => {
    a = a[key];
    b = b[key];
    return getTimeInt(a) - getTimeInt(b);
  });
  if (order === 'desc') {
    ASCarr.reverse();
  }
  return ASCarr
};

// 大小
const sortListBySize = (vodList, key, order) => {
  if (!key) {
    return vodList
  }
  let ASCarr = vodList.sort((a, b) => {
    a = a[key];
    b = b[key];
    return (Number(a) || 0) - (Number(b) || 0);
  });
  if (order === 'desc') {
    ASCarr.reverse();
  }
  return ASCarr
};

